package fr.mavoixecrite;
import android.content.Context;import android.widget.Button;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;import java.io.*;import java.util.*;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,35})
public class ChoiceCardTest {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{DataFile.NAME,DataFile.NAME+".new","phrases-v2.json"})new File(c.getFilesDir(),n).delete();for(String n:new String[]{"options","draft","MainActivity","conversation","voice"})c.getSharedPreferences(n,0).edit().clear().commit();c.getSharedPreferences("options",0).edit().putBoolean("correct",false).commit();}
 @Test public void newInstallationHasOnePainCard()throws Exception{CardStore s=new CardStore(c);assertFalse(s.all().stream().anyMatch(x->x.id.equals("default-8")));assertEquals(1,s.all().stream().filter(x->x.id.equals("template-pain")).count());}
 @Test public void oldDuplicateRemovedAndFavoritePreserved()throws Exception{List<CardStore.Card> old=CardStore.defaults();CardStore.Card plain=new CardStore.Card("default-8","Besoins","J’ai mal","help");plain.favorite=true;old.add(plain);JSONObject root=DataFile.snapshot(c);root.put("cards",CardStore.encode(old,CardStore.DEFAULT_PRESENTATION));DataFile.write(c,root);CardStore migrated=new CardStore(c);assertFalse(migrated.all().stream().anyMatch(x->x.id.equals("default-8")));assertTrue(migrated.favorites().stream().anyMatch(x->x.id.equals("template-pain")));assertEquals(migrated.all().size(),DataFile.snapshot(c).getJSONObject("cards").getJSONArray("items").length());}
 @Test public void customizedOldCardIsNotDeleted()throws Exception{List<CardStore.Card> old=CardStore.defaults();old.add(new CardStore.Card("default-8","Besoins","J’ai mal aux jambes","help"));JSONObject root=DataFile.snapshot(c);root.put("cards",CardStore.encode(old,CardStore.DEFAULT_PRESENTATION));DataFile.write(c,root);assertTrue(new CardStore(c).all().stream().anyMatch(x->x.text.equals("J’ai mal aux jambes")));}
 @Test public void plainPainIsKeptIfChoiceWasDeleted()throws Exception{List<CardStore.Card> old=CardStore.defaults();old.removeIf(x->x.id.equals("template-pain"));old.add(new CardStore.Card("default-8","Besoins","J’ai mal","help"));assertTrue(CardStore.parse(CardStore.encode(old,CardStore.DEFAULT_PRESENTATION)).stream().anyMatch(x->x.id.equals("default-8")));}
 @Test public void identicalCardCannotBeCreatedAgain()throws Exception{CardStore s=new CardStore(c);assertThrows(IOException.class,()->s.save(new CardStore.Card("duplicate","Essentiel"," bonjour ","chat")));}
 CardStore.Card oldWant(){CardStore.Card card=new CardStore.Card("template-want","Besoins","Je voudrais …","chat");card.choices.addAll(Arrays.asList("un verre d’eau","manger","me reposer","aller aux toilettes"));return card;}
 @Test public void redundantWantIsRemovedAndFavoritesStayAvailable()throws Exception{assertFalse(new CardStore(c).all().stream().anyMatch(x->x.id.equals("template-want")));List<CardStore.Card> old=CardStore.defaults();CardStore.Card want=oldWant();want.favorite=true;old.add(want);List<CardStore.Card> migrated=CardStore.parse(CardStore.encode(old,CardStore.DEFAULT_PRESENTATION));assertFalse(migrated.stream().anyMatch(x->x.id.equals("template-want")));assertEquals(4,migrated.stream().filter(x->x.favorite).count());}
 @Test public void personalizedWantRemains()throws Exception{List<CardStore.Card> old=CardStore.defaults();CardStore.Card want=oldWant();want.choices.add("un café");old.add(want);assertTrue(CardStore.parse(CardStore.encode(old,CardStore.DEFAULT_PRESENTATION)).stream().anyMatch(x->x.id.equals("template-want")));}
 @Test public void wantIsNotLostWhenUserRemovedDirectCases()throws Exception{List<CardStore.Card> old=CardStore.defaults();old.removeIf(x->x.id.equals("default-6"));old.add(oldWant());assertTrue(CardStore.parse(CardStore.encode(old,CardStore.DEFAULT_PRESENTATION)).stream().anyMatch(x->x.id.equals("template-want")));}
 @Test public void choiceHintDiffersFromImmediateSpeech(){try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();AppTest.find(a.getWindow().getDecorView(),"Besoins").performClick();Button choice=AppTest.find(a.getWindow().getDecorView(),"J’ai mal …");assertNotNull(choice);assertTrue(choice.getText().toString().contains("Choisir"));assertFalse(AppTest.find(a.getWindow().getDecorView(),"J’ai soif").getText().toString().contains("Choisir"));}}
}
